mapper.select:
SELECT 0 AS rec_idx, 0 AS user_idx, st.spot_idx, '' AS rec_reason, 0 AS rec_score, st.name AS spot_name, st.region, ( SELECT si.image_url FROM SPOT_IMAGE si WHERE si.spot_idx = st.spot_idx ORDER BY si.image_idx ASC LIMIT 1 ) AS thumb_url, COALESCE(( SELECT ROUND(AVG(r.rating), 1) FROM SPOT_REVIEW r WHERE r.spot_idx = st.spot_idx ), 0.0) AS rating_avg_real, (SELECT COUNT(*) FROM SPOT_REVIEW r WHERE r.spot_idx = st.spot_idx) AS review_count_real, (SELECT COUNT(*) FROM SPOT_LIKE sl WHERE sl.spot_idx = st.spot_idx) AS like_count_real, 0 AS tag_match_count FROM SPOT_TRAVEL st WHERE 1=1 /* ★ 현재 보고 있는 여행지 제외 */
AND st.spot_idx != #{currentSpotIdx}
ORDER BY ( SELECT COUNT(*) FROM SPOT_VIEW_LOG svl WHERE svl.spot_idx = st.spot_idx AND svl.viewed_at >= DATE_SUB(NOW(), INTERVAL 7 DAY) ) DESC, (SELECT COUNT(*) FROM SPOT_LIKE sl WHERE sl.spot_idx = st.spot_idx) DESC LIMIT 3

SELECT DISTINCT spot_idx
FROM   SPOT_RECOMMEND
WHERE  user_idx = #{userIdx}
